<template><view class="filter-bar"><view v-for="item in items" :key="item.key" :class="['filter-item',{active:value===item.key}]" hover-class="tap-active" @tap="$emit('input',item.key)">{{item.label}}</view></view></template>
<script>export default{emits:['input'],props:{value:{type:String,default:''},items:{type:Array,default:()=>[]}}}</script>
<style scoped>.filter-bar{height:86rpx;padding:0 18rpx;display:flex;align-items:center;background:var(--surface);border-bottom:1rpx solid var(--line)}.filter-item{position:relative;min-width:0;flex:1;height:100%;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:26rpx}.filter-item.active{color:var(--primary);font-weight:700}.filter-item.active::after{content:'';position:absolute;left:30%;right:30%;bottom:0;height:5rpx;border-radius:5rpx;background:var(--primary)}</style>
